package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import java.util.*;import it.unimi.dsi.fastutil.ints.*;import it.unimi.dsi.fastutil.longs.*;import team.creative.littletiles.common.math.box.*;import team.creative.littletiles.common.math.box.collection.*;
public final class FlatWallFaces {
 public static List<int[]> build(LittleBoxes boxes,int axis,int low,int high){var cached=WallHeightCache.faces(boxes,axis,low,high);if(cached!=null)return cached;int u=(axis+1)%3,v=(axis+2)%3;var rows=new Int2ObjectOpenHashMap<IntArrayList>();for(var b:boxes.all())for(int row=min(b,v);row<max(b,v);row++){var spans=rows.get(row);if(spans==null){spans=new IntArrayList();rows.put(row,spans);}int lo=min(b,u),hi=max(b,u);int i=0;while(i<spans.size()&&spans.getInt(i+1)<lo)i+=2;int end=i;while(end<spans.size()&&spans.getInt(end)<=hi){lo=Math.min(lo,spans.getInt(end));hi=Math.max(hi,spans.getInt(end+1));end+=2;}if(i==end){spans.add(i,lo);spans.add(i+1,hi);}else{spans.set(i,lo);spans.set(i+1,hi);spans.removeElements(i+2,end);}}
 var result=new ArrayList<int[]>();int[] keys=rows.keySet().toIntArray();Arrays.sort(keys);var previous=new Long2ObjectOpenHashMap<int[]>();var current=new Long2ObjectOpenHashMap<int[]>();var edgePrev=new Long2ObjectOpenHashMap<int[]>();var edgeNow=new Long2ObjectOpenHashMap<int[]>();int last=Integer.MIN_VALUE;
 for(int row:keys){if((long)last+1!=row){previous.clear();edgePrev.clear();}current.clear();edgeNow.clear();var spans=rows.get(row);
 for(int i=0;i<spans.size();i+=2){int lo=spans.getInt(i),hi=spans.getInt(i+1);long key=((long)lo<<32)|(hi&0xffffffffL);var cap=previous.get(key);if(cap!=null){cap[8]=row+1;result.get(cap[9])[8]=row+1;}else{cap=new int[]{axis,0,low,u,v,lo,hi,row,row+1,result.size()+1};result.add(cap);result.add(new int[]{axis,1,high,u,v,lo,hi,row,row+1});}current.put(key,cap);
 for(int sign=0;sign<2;sign++){int plane=sign==0?lo:hi;long edge=((long)plane<<1)|sign;var face=edgePrev.get(edge);if(face!=null)face[6]=row+1;else{face=new int[]{u,sign,plane,v,axis,row,row+1,low,high};result.add(face);}edgeNow.put(edge,face);}}
 difference(result,spans,rows.get(row-1),v,0,row,u,axis,low,high);difference(result,spans,rows.get(row+1),v,1,row+1,u,axis,low,high);
 var swap=previous;previous=current;current=swap;swap=edgePrev;edgePrev=edgeNow;edgeNow=swap;last=row;}
 WallHeightCache.rememberFaces(boxes,axis,result);return result;}
 private static void difference(List<int[]> out,IntArrayList own,IntArrayList other,int axis,int sign,int plane,int u,int height,int low,int high){int j=0;for(int i=0;i<own.size();i+=2){int lo=own.getInt(i),hi=own.getInt(i+1);if(other!=null){while(j<other.size()&&other.getInt(j+1)<=lo)j+=2;for(int k=j;k<other.size()&&other.getInt(k)<hi;k+=2){if(other.getInt(k)>lo)out.add(new int[]{axis,sign,plane,u,height,lo,Math.min(hi,other.getInt(k)),low,high});lo=Math.max(lo,other.getInt(k+1));if(lo>=hi)break;}}if(lo<hi)out.add(new int[]{axis,sign,plane,u,height,lo,hi,low,high});}}
 private static int min(LittleBox b,int a){return a==0?b.minX:a==1?b.minY:b.minZ;}private static int max(LittleBox b,int a){return a==0?b.maxX:a==1?b.maxY:b.maxZ;}
}
